# O salário padrão de uma pessoa num clube (STAFF_CONTRACT::default_staff_contract 0x864550, staff_contracts.cpp;
# fechamento do leitor D do mapa do mercado, 11/11/2026). Chamada pelo contrato desejado (0x85fc50, três vezes), pela
# vontade de vir (staff_interest_in_joining_club 0x846920, Rust: o portão do salário), pela vontade da comissão
# (0x844780), pelos lances (0x842e10, 0x83f3a0), pela folha (update_wage_bill 0x598370, Rust) e pela 0x85e960.
# Igual no cm0102-1080.exe (0x20c4 bytes conferidos, com as três tabelas de salto).
# Convenções conferidas na desmontagem:
# - a rotina: stdcall(pessoa, clube, flag, estatuto, cargo, tipo), ret 0x18, devolve o float em st0 (lido de um f32);
#   ecx é sobrescrito na entrada (mov ecx, [0xae1050]): o invólucro thiscall do exe_calls.rs passa um ecx que não conta;
# - 0x4cf5a0 (get_contract): ecx = [0xae1050]; push pessoa -> thiscall ret 4 (o resultado da primeira vai a [0xae1080]);
# - 0x4cf5f0 (get_contract_for_club): ecx = [0xae1050]; push clube; push pessoa -> thiscall ret 8;
# - 0x549e50 (club_is_in_major_nation): push clube; add esp, 4 -> cdecl, só o al conta (Rust, chamada direta);
# - 0x54cdb0 (Date::days_since): push [pessoa+0x42]; push [pessoa+0x3e]; mov ecx, 0xae2c90 -> thiscall ret 8;
# - 0x547770 (club_is_in_season): push 0xae2c90; push clube; add esp, 8 -> cdecl;
# - 0x5a0590 (get_club_finance): ecx = [0xae2a38]; push clube -> thiscall ret 4;
# - 0x5968d0 (get_max_wage): push estatuto (o dword inteiro, com o byte baixo regravado quando calculado); push pessoa;
#   ecx = finanças -> thiscall ret 8;
# - 0x945ff0 (pow): fld base; fld expoente -> game_pow; 0x945640 (_ftol) -> ftol;
# - 0x944c9f (sprintf, sem ficha de jogador): push id; push [+8]; push [+4]; push formato; push 0xde1f64; add esp, 0x14;
# - 0x946a04 (rand), 0x945e40 (__allmul por 4), 0x945e80 (__alldiv por 0x8000): o sorteio de quem não tem ficha.
# Comparador: compare_staff_contract_default_staff_contract (stdcall: a original e a cópia do mesmo estado de
# [0xae1080] e da semente do rand() [0xad6c30]; o float devolvido bit a bit).
# Determinismo: os slots de argumento que a original reusa como rascunho (+0x3c clube, +0x48 cargo, +0x4c tipo) são
# relidos só antes de ser sobrescritos; o fim usa o clube em ebx.
SAVE = False
